# Terraform Module: S3 + RDS + IAM

Structure:

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── backend.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
└── modules/
    ├── s3/
    ├── rds/
    └── iam/
```

---

## modules/s3

**main.tf**
```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_arn != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id     = rule.value.id
      status = "Enabled"
      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class
      }
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "${var.bucket_name}-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = ["s3:GetReplicationConfiguration", "s3:ListBucket", "s3:GetObjectVersionForReplication", "s3:GetObjectVersionAclForReplication", "s3:GetObjectVersionTaggingForReplication", "s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
      Resource = [
        aws_s3_bucket.this.arn,
        "${aws_s3_bucket.this.arn}/*",
        "arn:aws:s3:::*"
      ]
    }]
  })
}
```

**variables.tf**
```hcl
variable "bucket_name" { type = string }

variable "kms_key_arn" {
  type    = string
  default = null
}

variable "replication_enabled" {
  type    = bool
  default = false
}

variable "replication_rules" {
  type = list(object({
    id                    = string
    destination_bucket_arn = string
    storage_class         = optional(string, "STANDARD")
  }))
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

**outputs.tf**
```hcl
output "bucket_arn" { value = aws_s3_bucket.this.arn }
output "bucket_name" { value = aws_s3_bucket.this.id }
```

