## modules/rds

**main.tf**
```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-db-subnets"
  subnet_ids = var.subnet_ids
}

resource "aws_security_group" "db" {
  name_prefix = "${var.name}-db-"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "this" {
  identifier             = var.name
  engine                 = "postgres"
  engine_version         = var.engine_version
  instance_class         = var.instance_class
  allocated_storage      = var.allocated_storage
  db_name                = var.database_name
  username               = var.database_username
  password               = var.database_password   # supplied via SOPS-decrypted var file
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]

  multi_az                   = var.multi_az
  storage_encrypted          = true
  deletion_protection        = true
  publicly_accessible        = false
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${var.name}-final"
  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  tags = var.tags
}
```

**variables.tf**
```hcl
variable "name"                 { type = string }
variable "vpc_id"               { type = string }
variable "subnet_ids"           { type = list(string) }
variable "allowed_security_groups" {
  type    = list(string)
  default = []
}
variable "instance_class"       { type = string }
variable "engine_version"       { type = string }
variable "allocated_storage"    { type = number, default = 20 }
variable "multi_az"             { type = bool, default = false }
variable "database_name"        { type = string }
variable "database_username"    { type = string }
variable "database_password"    { type = string, sensitive = true }
variable "tags"                 { type = map(string), default = {} }
```

**outputs.tf**
```hcl
output "endpoint" {
  value     = aws_db_instance.this.address
  sensitive = false
}
output "db_instance_arn" { value = aws_db_instance.this.arn }
```

