## modules/iam

**main.tf**
```hcl
data "aws_iam_policy_document" "oidc_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_url, "https://", "")}:sub"
      values   = ["system:serviceaccount:${var.k8s_namespace}:${var.service_account}"]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.oidc_trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "bucket_access" {
  name = "${var.role_name}-s3"
  role = aws_iam_role.service_account.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket", "s3:GetBucketVersioning"]
        Resource = [
          var.bucket_arn,
          "${var.bucket_arn}/*"
        ]
      }
    ]
  })
}
```

**variables.tf**
```hcl
variable "role_name"          { type = string }
variable "oidc_provider_arn"  { type = string }
variable "oidc_provider_url"  { type = string }
variable "k8s_namespace"      { type = string }
variable "service_account"    { type = string }
variable "bucket_arn"         { type = string }
variable "tags"               { type = map(string), default = {} }
```

**outputs.tf**
```hcl
output "role_arn" { value = aws_iam_role.service_account.arn }
```

