## Root module

**main.tf**
```hcl
data "aws_vpc" "default" {
  tags = { Name = var.vpc_name }
}

data "aws_subnets" "db" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

module "s3" {
  source = "./modules/s3"

  bucket_name         = "${var.environment}-app-assets-${data.aws_caller_identity.current.account_id}"
  replication_enabled = var.s3_replication_enabled
  replication_rules   = var.s3_replication_rules
  kms_key_arn         = var.kms_key_arn
  tags                = local.tags
}

module "rds" {
  source = "./modules/rds"

  name                   = "${var.environment}-app-db"
  vpc_id                 = data.aws_vpc.default.id
  subnet_ids             = data.aws_subnets.db.ids
  allowed_security_groups = [var.app_security_group_id]
  instance_class         = var.db_instance_class
  multi_az               = var.db_multi_az
  database_name          = "appdb"
  database_username      = "appuser"
  database_password      = var.db_password
  tags                   = local.tags
}

module "iam" {
  source = "./modules/iam"

  role_name          = "${var.environment}-app-sa"
  oidc_provider_arn  = var.oidc_provider_arn
  oidc_provider_url  = var.oidc_provider_url
  k8s_namespace      = "app"
  service_account    = "app-sa"
  bucket_arn         = module.s3.bucket_arn
  tags               = local.tags
}

data "aws_caller_identity" "current" {}

locals {
  tags = merge(var.tags, { Environment = var.environment })
}
```

**variables.tf**
```hcl
variable "environment" { type = string }
variable "vpc_name"    { type = string }
variable "app_security_group_id" { type = string }
variable "oidc_provider_arn"     { type = string }
variable "oidc_provider_url"     { type = string }

variable "db_instance_class" { type = string }
variable "db_multi_az"       { type = bool, default = false }
variable "db_password"       { type = string, sensitive = true }

variable "kms_key_arn"             { type = string, default = null }
variable "s3_replication_enabled"  { type = bool, default = false }
variable "s3_replication_rules" {
  type = list(object({
    id                     = string
    destination_bucket_arn = string
    storage_class          = optional(string, "STANDARD")
  }))
  default = []
}

variable "tags" { type = map(string), default = {} }
```

**outputs.tf**
```hcl
output "bucket_name" { value = module.s3.bucket_name }
output "db_endpoint" { value = module.rds.endpoint }
output "sa_role_arn" { value = module.iam.role_arn }
```

**backend.tf** — per-environment state isolation (workspaces or key-based):
```hcl
terraform {
  backend "s3" {
    bucket         = "mycompany-tfstate"
    key            = "app/terraform.tfstate"   # use -backend-config per env, or workspaces
    region         = "us-east-1"
    dynamodb_table = "tflocks"
    encrypt        = true
  }
  required_version = ">= 1.5"
}
```

